#include <cuda_runtime.h>
#include "../dct8x8-cuda/kernels.cu"
#include "../dct8x8-cuda/DCT8x8_gold.cu"
#include <cstdio>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <chrono>
#define CU(x) do{if((x)!=cudaSuccess)abort();}while(0)
struct F{int w,h,s;std::vector<float>x,gold[2];std::vector<double>math[2];float *dx,*dy[2];F(int f){w=f==1?64:f==2?67:32;h=f==1?32:f==2?35:16;s=f==2?73:w;x.assign(s*h,0);if(f==1){srand(2009);for(float&v:x)v=float(rand())/float(RAND_MAX);}else if(f==2){for(size_t i=0;i<x.size();i++)x[i]=float(int((13*i+5)%257)-128)/128;}else if(f==3)std::fill(x.begin(),x.end(),.25f);else x[3*s+5]=1;CU(cudaMalloc(&dx,x.size()*4));CU(cudaMemcpy(dx,x.data(),x.size()*4,cudaMemcpyHostToDevice));double basis[8][8];for(int k=0;k<8;k++)for(int j=0;j<8;j++)basis[k][j]=k==0?sqrt(1./8):.5*cos((2*j+1)*k*acos(-1.)/16);for(int d=0;d<2;d++){gold[d].assign(x.size(),-123.25f);DCT8x8CPU(gold[d].data(),x.data(),s,h,w,d?777:666);math[d].assign(x.size(),-123.25);for(int by=0;by+7<h;by+=8)for(int bx=0;bx+7<w;bx+=8)for(int v=0;v<8;v++)for(int u=0;u<8;u++){double z=0;for(int n=0;n<8;n++)for(int m=0;m<8;m++)z+=double(x[(by+n)*s+bx+m])*(d?basis[m][u]*basis[n][v]:basis[u][m]*basis[v][n]);math[d][(by+v)*s+bx+u]=z;}CU(cudaMalloc(&dy[d],x.size()*4));std::vector<float>init(x.size(),-123.25f);CU(cudaMemcpy(dy[d],init.data(),init.size()*4,cudaMemcpyHostToDevice));}}
void launch(int d){DCT8x8(dy[d],dx,s,h,w,d?777:666);}};
int main(int argc,char**argv){int rep=argc>1?atoi(argv[1]):20;std::vector<F>fs;std::vector<float>prefix;for(int f=1;f<=4;f++){fs.emplace_back(f);auto&q=fs.back();prefix.insert(prefix.end(),{float(q.w),float(q.h),float(q.s)});prefix.insert(prefix.end(),q.x.begin(),q.x.end());for(int d=0;d<2;d++)q.launch(d);}CU(cudaDeviceSynchronize());for(int trial=1;trial<=5;trial++){for(auto&q:fs){std::vector<float>init(q.x.size(),-123.25f);for(int d=0;d<2;d++)CU(cudaMemcpy(q.dy[d],init.data(),init.size()*4,cudaMemcpyHostToDevice));}CU(cudaDeviceSynchronize());auto st=std::chrono::steady_clock::now();for(int z=0;z<rep;z++)for(auto&q:fs)for(int d=0;d<2;d++)q.launch(d);CU(cudaDeviceSynchronize());double elapsed=std::chrono::duration<double>(std::chrono::steady_clock::now()-st).count()/rep;std::vector<float>got;double err=0,maxl2=0;bool ok=true;for(auto&q:fs)for(int d=0;d<2;d++){std::vector<float>g(q.x.size());CU(cudaMemcpy(g.data(),q.dy[d],g.size()*4,cudaMemcpyDeviceToHost));double numer=0,denom=0;for(size_t i=0;i<g.size();i++){double delta=fabs(double(g[i])-q.math[d][i]);err=std::max(err,delta);ok&=std::isfinite(g[i])&&delta<=1e-5+1e-6*fabs(q.math[d][i]);if(q.math[d][i]!=-123.25){numer+=pow(double(g[i])-q.gold[d][i],2);denom+=pow(double(q.gold[d][i]),2);}}double l2=sqrt(numer/std::max(denom,1e-30));maxl2=std::max(maxl2,l2);ok&=l2<1e-6;got.insert(got.end(),g.begin(),g.end());}auto art=prefix;art.insert(art.end(),got.begin(),got.end());const char*dir=getenv("STUDY_OUTPUT_DIR");std::string path=std::string(dir?dir:".")+"/output_trial"+std::to_string(trial)+".bin";FILE*fp=fopen(path.c_str(),"wb");fwrite(art.data(),4,art.size(),fp);fclose(fp);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%.17g,\"max_rel_error\":0.0,\"native_CPU_relative_L2_max\":%.17g,\"timing_region\":\"eight_full_forward_inverse_DCTs_four_images_no_transfers\",\"jit_excluded\":true,\"internal_repeats\":%d,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float32\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,elapsed,ok?"true":"false",got.size(),err,maxl2,rep,path.c_str(),art.size());if(!ok)return 2;}for(auto&q:fs){cudaFree(q.dx);for(auto y:q.dy)cudaFree(y);}}
